SELECT setval(pg_get_serial_sequence('store_sales_daily', 'daily_summary_id'), COALESCE(max(daily_summary_id), 1)) FROM store_sales_daily;
SELECT setval(pg_get_serial_sequence('store_sales_monthly', 'monthly_summary_id'), COALESCE(max(monthly_summary_id), 1)) FROM store_sales_monthly;
SELECT setval(pg_get_serial_sequence('users', 'user_id'), COALESCE(max(user_id), 1)) FROM users;
